import { useState } from 'react';
import { 
  Box, 
  IconButton, 
  Drawer, 
  MenuItem, 
  Divider, 
  Button,
  ListItemIcon,
  ListItemText
} from '@mui/material';
import { Link } from 'react-router-dom';
import MenuIcon from '@mui/icons-material/Menu';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import HomeIcon from '@mui/icons-material/Home';
import NoteIcon from '@mui/icons-material/Note';
import ArticleIcon from '@mui/icons-material/Article';
import WorkIcon from '@mui/icons-material/Work';
import AccountBalanceIcon from '@mui/icons-material/AccountBalance';
import PersonIcon from '@mui/icons-material/Person';
import LanguageIcon from '@mui/icons-material/Language';
import Brightness4Icon from '@mui/icons-material/Brightness4';

import PersonAddIcon from '@mui/icons-material/PersonAdd';
import LockResetIcon from '@mui/icons-material/LockReset';
import LogoutIcon from '@mui/icons-material/Logout';
import LanguageSwitchComponent from './LanguageSwitch';
import ThemeSwitch from './ThemeSwitch';
import { translations } from './translations';
import { useUser } from '../../../context/UserContext';
import UserService from '../../../services/UserService';
import PasswordResetModal from './PasswordResetModal';

const MobileDrawer = ({ 
  language, 
  toggleLanguage, 
  toggleTheme, 
  handleLoginOpen, 
  handleSignupOpen 
}) => {
  const [open, setOpen] = useState(false);
  const [passwordResetOpen, setPasswordResetOpen] = useState(false); // State for password reset modal
  const { userState, setUser } = useUser();

  const toggleDrawer = (newOpen) => () => {
    setOpen(newOpen);
  };

  const handleLogout = async () => {
    const userData = await UserService.getNonuserJWT();
    setUser(userData);
    setOpen(false);
  };

  // Handle opening the password reset modal
  const handlePasswordResetOpen = () => {
    setPasswordResetOpen(true);
    setOpen(false); // Optionally close the drawer when opening the modal
  };

  return (
    <Box sx={{ display: { xs: 'flex', md: 'none' }, gap: 1 }}>
      <IconButton aria-label="Menu button" onClick={toggleDrawer(true)}>
        <MenuIcon />
      </IconButton>
      <Drawer
        anchor="top"
        open={open}
        onClose={toggleDrawer(false)}
        PaperProps={{
          sx: { 
            top: 'var(--template-frame-height, 0px)', 
            borderBottomLeftRadius: '5px',
            borderBottomRightRadius: '5px'
          },
        }}
      >
        <Box sx={{ 
          p: 2, 
          backgroundColor: 'background.default'
        }}>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
            <IconButton onClick={toggleDrawer(false)}>
              <CloseRoundedIcon />
            </IconButton>
          </Box>
          
          <MenuItem component={Link} to="/" >
            <ListItemIcon sx={{ marginRight: 2 }}>
              <HomeIcon />
            </ListItemIcon>
            <ListItemText primary={translations[language].home} />
          </MenuItem>
          
          <MenuItem component={Link} to="/notes">
            <ListItemIcon sx={{ marginRight: 2 }}>
              <NoteIcon />
            </ListItemIcon>
            <ListItemText primary={translations[language].notes} />
          </MenuItem>
          
          <MenuItem component={Link} to="/blogs">
            <ListItemIcon  sx={{ marginRight: 2 }}>
              <ArticleIcon />
            </ListItemIcon>
            <ListItemText primary={translations[language].blogs} />
          </MenuItem>
          
          <MenuItem component={Link} to="/projects">
            <ListItemIcon  sx={{ marginRight: 2 }}>
              <WorkIcon />
            </ListItemIcon>
            <ListItemText primary={translations[language].projects} />
          </MenuItem>
          
          <MenuItem component={Link} to="/fin">
            <ListItemIcon  sx={{ marginRight: 2 }}>
              <AccountBalanceIcon/>
            </ListItemIcon>
            <ListItemText primary={translations[language].finance} />
          </MenuItem>
          
          <MenuItem component={Link} to="/profile">
            <ListItemIcon  sx={{ marginRight: 2 }}>
              <PersonIcon />
            </ListItemIcon>
            <ListItemText primary={translations[language].profile} />
          </MenuItem>
          
          {/* <MenuItem component={Link} to="/dashboard">{translations[language].dashboard}</MenuItem> */}
          
          <Divider sx={{ my: 3 }} />
          
          <MenuItem>
            <ListItemIcon  sx={{ marginRight: 0.5 }}>
              <LanguageIcon />
            </ListItemIcon>
            <Box sx={{ flexGrow: 1 }}>
              <LanguageSwitchComponent onClick={toggleLanguage} />
            </Box>
          </MenuItem>
          
          <MenuItem>
            <ListItemIcon  sx={{ marginRight: 0.5 }}>
              <Brightness4Icon />
            </ListItemIcon>
            <Box sx={{ flexGrow: 1 }}>
              <ThemeSwitch onClick={toggleTheme} />
            </Box>
          </MenuItem>
          
          <Divider sx={{ my: 3 }} />

          {userState.user_id === 0 ? (
            <>
              <MenuItem>
                <Button
                  color="primary"
                  variant="outlined"
                  fullWidth
                  onClick={handleLoginOpen}
                  startIcon={<PersonIcon />}
                >
                  {translations[language].login}
                </Button>
              </MenuItem>
              <MenuItem>
                <Button
                  color="primary"
                  variant="contained"
                  fullWidth
                  onClick={handleSignupOpen}
                  startIcon={<PersonAddIcon />}
                >
                  {translations[language].signup}
                </Button>
              </MenuItem>
            </>
          ) : (
            <>
              <MenuItem>
                <Button
                  color="primary"
                  variant="outlined"
                  fullWidth
                  onClick={handlePasswordResetOpen} // Updated to use the new handler
                  startIcon={<LockResetIcon />}
                >
                  {translations[language].password_reset}
                </Button>
              </MenuItem>
              <MenuItem>
                <Button
                  color="primary"
                  variant="contained"
                  fullWidth
                  onClick={handleLogout}
                  startIcon={<LogoutIcon />}
                >
                  {translations[language].logout}
                </Button>
              </MenuItem>
              <Divider sx={{ my: 1 }} />
              <MenuItem>
                <Button
                  color="info"
                  fullWidth
                  variant="text"
                  disabled
                  sx={{ textTransform: 'none', height: 18 }}
                  startIcon={<PersonIcon />}
                >
                  {userState.username}
                </Button>
              </MenuItem>
            </>
          )}
        </Box>
      </Drawer>

      {/* Password Reset Modal */}
      <PasswordResetModal
        open={passwordResetOpen}
        onClose={() => setPasswordResetOpen(false)}
        language={language}
      />
    </Box>
  );
};

export default MobileDrawer;