import { useState, useContext } from 'react';
import { Button, Menu, MenuItem } from '@mui/material';
import { translations } from './translations';
import { useUser } from '../../../context/UserContext';
import UserService from '../../../services/UserService';
import PasswordResetModal from './PasswordResetModal';

const UserMenu = ({ language, themeMode }) => {
  const { userState, setUser } = useUser();
  const [ anchorEl, setAnchorEl ] = useState(null);
  const [ passwordResetOpen, setPasswordResetOpen ] = useState(false);
  
  // Dynamic button color based on theme
  const buttonColor = themeMode === 'dark' ? '#64B5F6' : '#13479c';
    
  const handleLogout = async () => {
    const userData = await UserService.getNonuserJWT();
    setUser(userData);
    setAnchorEl(null);
  };

  const handlePasswordResetClick = () => {
    setAnchorEl(null);
    setPasswordResetOpen(true);
  };

  return (
    <>
      <Button
        variant="text"
        size="small"
        onClick={(e) => setAnchorEl(e.currentTarget)}
        sx={{ 
          textTransform: 'none',
          color: buttonColor, // Use your custom color
          '&:hover': {
            backgroundColor: themeMode === 'dark' 
              ? 'rgba(3, 169, 244, 0.08)' 
              : 'rgba(22, 112, 197, 0.08)',
          }
        }}
        aria-label={`User menu for ${userState.username}`}
        aria-haspopup="true"
        aria-expanded={Boolean(anchorEl)}
      >
        {userState.username}
      </Button>
      
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={() => setAnchorEl(null)}
        sx={{ 
          ml: 0,
          '& .MuiPaper-root': {
            backgroundColor: themeMode === 'dark' ? '#424242' : '#ffffff',
            color: themeMode === 'dark' ? '#ffffff' : '#000000',
          }
        }}
        MenuListProps={{
          'aria-labelledby': 'user-menu-button',
        }}
        disableScrollLock={true}
      >
        <MenuItem 
          onClick={handlePasswordResetClick} 
          sx={{ 
            fontSize: '0.85rem',
            '&:hover': {
              backgroundColor: themeMode === 'dark' 
                ? 'rgba(255, 255, 255, 0.08)' 
                : 'rgba(0, 0, 0, 0.04)',
            }
          }}
        >
          {translations[language].password_reset || "Reset Password"}
        </MenuItem>
        <MenuItem 
          onClick={handleLogout} 
          sx={{ 
            fontSize: '0.85rem',
            '&:hover': {
              backgroundColor: themeMode === 'dark' 
                ? 'rgba(255, 255, 255, 0.08)' 
                : 'rgba(0, 0, 0, 0.04)',
            }
          }}
        >
          {translations[language].logout || 'Log out'}
        </MenuItem>
      </Menu>

      <PasswordResetModal
        open={passwordResetOpen}
        onClose={() => setPasswordResetOpen(false)}
        language={language}
      />
    </>
  );
};

export default UserMenu;